{
  "candidates": [
    {
      "subpart": "PPPP",
      "title": "Plastic Parts and Products Surface Coating NESHAP (surface coating of plastic parts and products)",
      "criteria": [
        {
          "criterion": "If the methylene chloride step is an application of a material for the purpose of bonding plastic surfaces (i.e., an 'adhesive' or 'coating' applied to a substrate), then that operation is a 'surface coating' covered by this subpart.",
          "citations": [
            "40 CFR 63.4481(a)(1)",
            "40 CFR 63.4581"
          ]
        },
        {
          "criterion": "If the coating/adhesive materials used in that operation contain organic HAP and you use 378 liters (100 gallons) or more per year at a source that is a major source (or located at a major source), then the affected source is subject to this subpart.",
          "citations": [
            "40 CFR 63.4481(b)"
          ]
        },
        {
          "criterion": "If the coating operation uses only coatings, thinners, other additives, and cleaning materials that contain no organic HAP (as determined per the subpart), then the operation is not subject to this subpart.",
          "citations": [
            "40 CFR 63.4481(c)(1)",
            "40 CFR 63.4541(a)"
          ]
        },
        {
          "criterion": "If the activity falls within any of the enumerated exclusions in § 63.4481(c)(2)–(17) (for example certain research/laboratory activities, processes covered by other NESHAP subparts, web or in-mold coating exclusions, etc.), then the operation is not subject to this subpart.",
          "citations": [
            "40 CFR 63.4481(c)"
          ]
        },
        {
          "criterion": "If the material applied is an adhesive that is a 'product used on humans or animals' or is adhesive tape/contact paper or an adhesive pre‑incorporated on a substrate, then it is not treated as an 'adhesive' under this subpart and may not be covered as a coating/adhesive here.",
          "citations": [
            "40 CFR 63.4581"
          ]
        }
      ]
    },
    {
      "subpart": "A",
      "title": "General Provisions (definitions, performance testing, monitoring)",
      "criteria": [
        {
          "criterion": "If your source is subject to a relevant standard under part 63 (for example Subpart PPPP), then Subpart A's General Provisions apply as part of that relevant standard.",
          "citations": [
            "40 CFR 63.2"
          ]
        },
        {
          "criterion": "If the relevant standard requires performance testing, then the owner/operator must perform required performance tests within 180 days of the compliance date (unless a waiver or other provision applies).",
          "citations": [
            "40 CFR 63.7(a)(2)"
          ]
        },
        {
          "criterion": "If the relevant standard requires installation or use of a continuous monitoring system (CMS) or other monitoring, then monitoring must be conducted, operated, and quality‑assured in accordance with § 63.8.",
          "citations": [
            "40 CFR 63.8"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Determine whether the methylene chloride application is performed for the purpose of bonding (i.e., is the material applied to bond surfaces) versus being only a cleaner or surface prep; document how and why the solvent is applied.",
    "Quantify the annual volume of methylene chloride (and any other coatings/thinners/additives/cleaning materials used in the bonding step) in liters or gallons per year (include the six new lines projected use).",
    "Obtain manufacturer/supplier formulation data or test data for the methylene chloride and any mixtures to determine organic HAP content and mass fraction of coating solids (use Method 311 or Method 24 paths per subpart guidance if needed).",
    "Determine whether methylene chloride (and any other solvents used) is an organic HAP and calculate potential annual HAP emissions to evaluate whether the facility is a 'major source' (≥10 tpy single HAP or ≥25 tpy combined HAP).",
    "Verify whether the applied material leaves any coating solids or dry film on the part (document that no dry film remains and whether any volatile fraction reacts or becomes solids — relevant to reactive adhesive provisions).",
    "Check whether the adhesive/product can be considered a 'product used on humans or animals' or otherwise fits any of the specific exclusions in § 63.4481(c); document why each exclusion does or does not apply.",
    "If subject to the subpart, decide which compliance option you will use (compliant materials, emission rate without add‑on controls, or emission rate with add‑on controls) and collect the data required for that option (materials tracking, solids used, capture/control efficiencies if applicable).",
    "Establish whether performance testing and/or CMS will be required, note the applicable compliance date, and prepare to meet Subpart A requirements for test notifications, site‑specific test plans, and monitoring quality assurance (timing per § 63.7 and § 63.8)."
  ]
}

{
  "candidates": [
    {
      "subpart": "FFFFFF",
      "title": "Secondary Copper Smelters",
      "criteria": [
        {
          "criterion": "If a facility processes copper scrap in a blast furnace and converter or uses another pyrometallurgical purification process to produce anode copper from copper scrap, then it is a secondary copper smelter and subject to this subpart.",
          "citations": [
            "40 CFR 63.11158",
            "40 CFR 63.11153(a)"
          ]
        },
        {
          "criterion": "If a facility merely melts recycled copper scrap or copper-alloy scrap to produce ingots or for direct use in a manufacturing process (and does not use a pyrometallurgical purification process to produce anode copper), then it is not a secondary copper smelter and is not subject to this subpart.",
          "citations": [
            "40 CFR 63.11158"
          ]
        },
        {
          "criterion": "If the facility is a secondary copper smelter that is a new affected source (construction or reconstruction commenced on or after October 6, 2006) and is an area source of HAP, then this subpart applies to that new affected source.",
          "citations": [
            "40 CFR 63.11153(a)",
            "40 CFR 63.11153(b)"
          ]
        }
      ]
    },
    {
      "subpart": "ZZZZZZ",
      "title": "Aluminum, Copper, and Other Nonferrous Foundries",
      "criteria": [
        {
          "criterion": "If you operate a copper foundry that melts copper and pours molten copper into molds to manufacture complex castings and the affected source's annual metal melt production (existing) or annual metal melt capacity (new) for copper and other nonferrous metals is at least 600 tons per year, then this subpart applies.",
          "citations": [
            "40 CFR 63.11544(a)(4)",
            "40 CFR 63.11556"
          ]
        },
        {
          "criterion": "If you are a primary or secondary metal producer that casts molten copper to produce simple shapes such as sows, ingots, bars, rods, billets, or anode copper, then you are not a copper foundry and this subpart does not apply.",
          "citations": [
            "40 CFR 63.11556",
            "40 CFR 63.11544(a)"
          ]
        }
      ]
    },
    {
      "subpart": "TTTTTT",
      "title": "Secondary Nonferrous Metals Processing",
      "criteria": [
        {
          "criterion": "If you own or operate a secondary nonferrous metals processing facility that is an area source of hazardous air pollutant emissions, then this subpart applies.",
          "citations": [
            "40 CFR 63.11462(a)"
          ]
        }
      ]
    },
    {
      "subpart": "A",
      "title": "General Provisions",
      "criteria": [
        {
          "criterion": "If a relevant standard requires performance testing, then the owner or operator must perform the performance test within 180 days of the compliance date (unless another provision applies or a waiver/extension is obtained).",
          "citations": [
            "40 CFR 63.7(a)(2)"
          ]
        },
        {
          "criterion": "If a relevant standard requires continuous monitoring systems (CMS) or other monitoring, then monitoring must be conducted as set forth in § 63.8 and the CMS must be installed, operated, and maintained according to that section and any applicable relevant standard.",
          "citations": [
            "40 CFR 63.8(a)(2)",
            "40 CFR 63.8(c)(1)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Does the facility process copper scrap using a pyrometallurgical purification process (e.g., blast furnace/converter or other smelting process) specifically to produce anode copper from copper scrap?",
    "Is the final product anode copper (cast anodes shipped for electrolytic refining) or simple ingots/sows/other shapes for direct use?",
    "Does the operation use a smelting or melting furnace with fluxes producing molten material and slag (i.e., meet the subpart FFFFFF definition of smelting/melting furnace)?",
    "Was construction or reconstruction of the affected source commenced on or after October 6, 2006 (to determine new-source status under Subpart FFFFFF)?",
    "Is the facility an area source or a major source of HAP (i.e., potential to emit <10 tpy of any single HAP and <25 tpy combined HAP for area source determination)?",
    "For foundry applicability: what is the facility's annual metal melt production (existing) or annual metal melt capacity (new) for copper and other nonferrous metals (is it ≥600 tpy)?",
    "Does the facility melt and pour molten metal into molds to make complex castings (characteristic of a 'foundry') or cast simple shapes (excluded from 'copper foundry')?",
    "Does the facility meet any applicable local/state definitions or listings for 'secondary nonferrous metals processing' (check applicable definitions/permits or 40 CFR references available to the permitting authority)?"
  ]
}

{
  "candidates": [
    {
      "subpart": "M",
      "title": "National Emission Standards for Perchloroethylene Dry Cleaning Facilities",
      "criteria": [
        {
          "criterion": "if the dry cleaning facility uses perchloroethylene (PCE) then the provisions of this subpart apply to the owner or operator of the facility",
          "citations": [
            "40 CFR 63.320(a)"
          ]
        },
        {
          "criterion": "if a dry cleaning system is located in a building with a residence on or after December 21, 2020 then the owner or operator shall eliminate any emission of PCE from that dry cleaning system",
          "citations": [
            "40 CFR 63.322(o)(5)(i)"
          ]
        },
        {
          "criterion": "if the total yearly PCE consumption is less than 530 liters (140 gallons) per year for facilities meeting the conditions of §63.320(d) then the facility is exempt from many provisions of §§63.322, 63.323, and 63.324 but remains subject to §63.322(o)(5)(i)",
          "citations": [
            "40 CFR 63.320(d)",
            "40 CFR 63.322(o)(5)(i)"
          ]
        },
        {
          "criterion": "if the total yearly PCE consumption is less than 760 liters (200 gallons) per year for facilities described in §63.320(e) then the facility is exempt from many provisions of §§63.322, 63.323, and 63.324 but remains subject to §63.322(o)(5)(i)",
          "citations": [
            "40 CFR 63.320(e)",
            "40 CFR 63.322(o)(5)(i)"
          ]
        },
        {
          "criterion": "if the dry cleaning machine is coin-operated then it is exempt from the requirements of this subpart",
          "citations": [
            "40 CFR 63.320(j)"
          ]
        },
        {
          "criterion": "if the dry cleaning facility emits or has the potential to emit more than 9.1 megagrams per year (10 tons per year) of PCE then the facility is a major source (different major-source provisions in this subpart may apply)",
          "citations": [
            "40 CFR 63.320(g)"
          ]
        },
        {
          "criterion": "if the building contains a dwelling that meets the definition of 'residence' (excluding short-term housing occupied by the same person for less than 180 days) then that dwelling counts as a 'residence' for purposes of the Subpart M residence-related requirements",
          "citations": [
            "40 CFR 63.321"
          ]
        },
        {
          "criterion": "if construction or reconstruction of a dry cleaning system commenced on or after specified dates (e.g., December 9, 1991; December 21, 2005; July 27, 2006) then the compliance date and specific requirements applicable to that system follow the timelines in §63.320(b)",
          "citations": [
            "40 CFR 63.320(b)(1)",
            "40 CFR 63.320(b)(2)",
            "40 CFR 63.320(b)(3)"
          ]
        },
        {
          "criterion": "if a facility is located in a building with a residence, even if the residence is vacant at the time of notification, then the owner or operator had to report that fact under the notification provisions in §63.324(f)",
          "citations": [
            "40 CFR 63.324(f)(3)"
          ]
        }
      ]
    },
    {
      "subpart": "A",
      "title": "General Provisions (applicability, compliance dates, operation and maintenance)",
      "criteria": [
        {
          "criterion": "if you are an owner or operator of an affected source subject to a relevant standard under this part then you must operate and maintain the affected source and associated control and monitoring equipment in a manner consistent with safety and good air pollution control practices at all times",
          "citations": [
            "40 CFR 63.6(e)(1)(i)"
          ]
        },
        {
          "criterion": "if an area source later increases its emissions or potential to emit such that it becomes a major source then the source becomes subject to the relevant emission standards as provided in this part",
          "citations": [
            "40 CFR 63.6(a)(2)"
          ]
        },
        {
          "criterion": "if you are subject to a relevant standard under this part then you must develop a written startup, shutdown, and malfunction (SSM) plan describing procedures for operation and corrective action as required by §63.6(e)(3)",
          "citations": [
            "40 CFR 63.6(e)(3)"
          ]
        },
        {
          "criterion": "if a relevant standard requires performance testing or monitoring then the timing, conduct, and reporting of tests and monitoring are governed by the performance testing and monitoring requirements in §§63.7 and 63.8",
          "citations": [
            "40 CFR 63.7(a)(1)",
            "40 CFR 63.8(a)(1)"
          ]
        }
      ]
    },
    {
      "subpart": "EEEE",
      "title": "Industrial, Commercial, and Institutional Boilers: General provisions excerpt (references to applicability of General Provisions)",
      "criteria": [
        {
          "criterion": "if your source were subject to Subpart EEEE then Table 12 to that subpart determines which parts of the General Provisions (§§63.1–63.15) apply",
          "citations": [
            "40 CFR 63.2398"
          ]
        },
        {
          "criterion": "if equipment identified in §63.2338(b)(1)–(5) is in OLD operation then at those times you must be in compliance with the emission limitations, operating limits, and work practice standards in Subpart EEEE and operate consistent with §63.6(e)(1)(i)",
          "citations": [
            "40 CFR 63.2350(a)",
            "40 CFR 63.2350(b)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Confirm whether your facility uses perchloroethylene (PCE) at all (any purchases) and collect purchase receipts for the last 12 months to calculate yearly PCE consumption per §63.323(d).",
    "Determine the physical location of the dry cleaning machine(s): is any machine located in the same building that contains an apartment or other dwelling unit (identify address and unit)?",
    "If there is an apartment/dwelling, determine whether it meets the Subpart M definition of 'residence' (not short-term housing occupied by the same person for less than 180 days).",
    "Determine whether the apartment/dwelling is currently occupied or vacant (note: vacancy does not negate reporting or the residence-based requirement per §63.324(f)(3)).",
    "Identify the type of machine(s): dry-to-dry or transfer machine system, and whether any machine is coin-operated.",
    "Determine the date construction or reconstruction of each dry cleaning system commenced (to check which compliance dates apply under §63.320(b)).",
    "Calculate total yearly PCE consumption (sum of purchases for previous 12 months per §63.323(d)) to check exemptions/major-source thresholds (530 L/140 gal, 760 L/200 gal, 6,800 L/1,800 gal, 8,000 L/2,100 gal) and whether the facility is a major or area source under §63.320(g)/(h).",
    "If claiming exemption based on low consumption, verify which specific provisions you remain subject to (note that §63.322(o)(5)(i) remains applicable even for some exempted low-consumption configurations).",
    "Check whether any required notifications or notifications of compliance status have been submitted (including the §63.324 notifications and the July 28, 2008 certification items in §63.324(f)), and whether any extension requests under §63.6(i) have been sought or granted.",
    "If controls are installed (refrigerated condenser, carbon adsorber, vapor/vapor-barrier enclosure), gather equipment manuals, monitoring records, and operation procedures to confirm compliance with §63.322 and applicable monitoring/reporting (see §63.322, §63.323, §63.324)."
  ]
}

{
  "candidates": [
    {
      "subpart": "XXXXXX",
      "title": "Area Source Standards for Metal Fabrication and Finishing",
      "criteria": [
        {
          "criterion": "If you own or operate an area source that is primarily engaged (>=50% production as defined in §63.11522) in one of the nine metal fabrication and finishing source categories (e.g., Electrical and Electronic Equipment Finishing Operations) then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.11514(a)",
            "40 CFR 63.11522"
          ]
        },
        {
          "criterion": "If you use materials that contain, or have the potential to emit, metal fabrication and finishing HAP (MFHAP — compounds of cadmium, chromium, lead, manganese, or nickel at the specified thresholds) and you perform machining, dry grinding/dry polishing with machines, dry abrasive blasting, spray painting, or welding operations then the affected source provisions of this subpart apply.",
          "citations": [
            "40 CFR 63.11514(b)",
            "40 CFR 63.11516(b)"
          ]
        },
        {
          "criterion": "If your operations are research or laboratory facilities, or are tool or equipment repair operations, facility maintenance, or quality control activities, or are on-site operations at certain Federal agencies, or produce military munitions, then this subpart does not apply to those operations.",
          "citations": [
            "40 CFR 63.11514(e)",
            "40 CFR 63.11514(f)",
            "40 CFR 63.11514(g)",
            "40 CFR 63.11514(h)"
          ]
        }
      ]
    },
    {
      "subpart": "WWWWWW",
      "title": "Area Source Standards for Plating and Polishing",
      "criteria": [
        {
          "criterion": "If you own or operate a plating and polishing facility that is an area source and that is engaged in one or more listed processes (non-chromium electroplating, electroless or non-electrolytic plating, other non-electrolytic metal coating processes including thermal spraying, dry mechanical polishing after plating, electroforming, or electropolishing) and the facility uses or has emissions of plating and polishing metal HAP, then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.11504(a)(1)",
            "40 CFR 63.11504(a)(2)",
            "40 CFR 63.11504(a)(3)"
          ]
        },
        {
          "criterion": "If individual process units are subject to 40 CFR part 63 subpart N (chromium electroplating), are research and development or educational process units, are used strictly for repair/maintenance or restoration, or the process uses materials with plating metal HAP below the thresholds specified, then those process units are not subject to this subpart.",
          "citations": [
            "40 CFR 63.11505(d)(1)",
            "40 CFR 63.11505(d)(2)",
            "40 CFR 63.11505(d)(4)",
            "40 CFR 63.11505(d)(5)",
            "40 CFR 63.11505(d)(6)"
          ]
        },
        {
          "criterion": "If you operate tanks that contain plating/polishing metal HAP used for non-chromium electroplating/electroforming/electropolishing/electroless plating/other non-electrolytic metal coating, or thermal spraying operations that apply plating/polishing metal HAP, or dry mechanical polishing operations that emit plating/polishing metal HAP, then those units are covered as affected sources under this subpart.",
          "citations": [
            "40 CFR 63.11505(a)(1)",
            "40 CFR 63.11505(a)(2)",
            "40 CFR 63.11505(a)(3)"
          ]
        }
      ]
    },
    {
      "subpart": "A",
      "title": "General Provisions (Part 63)",
      "criteria": [
        {
          "criterion": "If an affected source is subject to a relevant standard then the performance testing requirements of §63.7 apply as specified in that section.",
          "citations": [
            "40 CFR 63.7(a)(1)"
          ]
        },
        {
          "criterion": "If an affected source is required to use a continuous monitoring system or other monitoring under a relevant standard then the monitoring requirements of §63.8 apply.",
          "citations": [
            "40 CFR 63.8(a)(1)",
            "40 CFR 63.8(a)(4)"
          ]
        },
        {
          "criterion": "If your stationary source is not a major source (i.e., emits less than the major source thresholds) then it is an area source for purposes of these Part 63 area-source subparts.",
          "citations": [
            "40 CFR 63.2"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Confirm whether the facility is an area source (potential to emit < 10 tpy single HAP and < 25 tpy total HAP) or a major source (use PTE calculation).",
    "Determine whether the facility is 'primarily engaged' (≥50% of production by volume/appropriate metric over the previous continuous 12 months) in one of the nine metal fabrication/finishing categories (including Electrical and Electronic Equipment Finishing Operations).",
    "List all metal fabrication and finishing activities performed on-site in the last 12 months (machining, dry grinding/polishing with machines, dry abrasive blasting, spray painting, welding, thermal spraying, plating, electroless plating, electropolishing, dry mechanical polishing, electroforming).",
    "For each material, check supplier formulation data/MSDS to determine if it contains MFHAP/plating-and-polishing metals at or above thresholds (cadmium, chromium, lead, or nickel ≥ 0.1% by weight; manganese ≥ 1.0% by weight).",
    "If performing welding, record welding rod usage on a rolling 12-month basis to see if it is ≥ 2,000 lb/yr (triggers additional welding requirements).",
    "If plating tanks are used, identify tank types (non-chromium vs chromium) and bath pH and chemicals to determine coverage or applicability of Subpart WWWWWW vs subpart N (chromium electroplating).",
    "Document whether any operations are research/laboratory, educational, facility maintenance, tool/equipment repair, quality control sampling, or military munitions production (possible exemptions).",
    "Inventory spray painting methods and equipment (HVLP, electrostatic, spray booths/waterwash, filter efficiencies) and worker training records if spray-applied paints containing MFHAP are used.",
    "Identify any dry abrasive blasting enclosures (totally enclosed/unvented vs vented) and whether capture and filtration controls are present and their manufacturer specifications.",
    "Assemble production fractions, process lists, material MSDS, emissions estimates, and records so you can prepare initial notification/notification of compliance status and the required records if the subpart(s) apply."
  ]
}

{
  "candidates": [
    {
      "subpart": "AAAAA",
      "title": "NESHAP for lime manufacturing plants (LMP)",
      "criteria": [
        {
          "criterion": "If you own or operate a lime manufacturing plant (LMP) that is a major source, or that is located at, or is part of, a major source of hazardous air pollutant (HAP) emissions, then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.7081(a)"
          ]
        },
        {
          "criterion": "If an establishment manufactures lime product (calcium oxide, calcium oxide with magnesium oxide, or dead burned dolomite) by calcination of limestone, dolomite, shells, or other calcareous substances, then it is an LMP for purposes of this subpart.",
          "citations": [
            "40 CFR 63.7081(a)(1)",
            "40 CFR 63.7143"
          ]
        },
        {
          "criterion": "If you have a lime kiln at an LMP that is a major source, then this subpart applies to each existing or new lime kiln and their associated cooler(s) and processed stone handling operations located at that LMP.",
          "citations": [
            "40 CFR 63.7082(a)"
          ]
        },
        {
          "criterion": "If the LMP is located at a kraft pulp mill, soda pulp mill, sulfite pulp mill, beet sugar manufacturing plant, or only processes sludge containing calcium carbonate from water softening processes, then the LMP is not subject to this subpart.",
          "citations": [
            "40 CFR 63.7081(a)"
          ]
        },
        {
          "criterion": "If the emission unit is a lime hydrator, then it is not subject to this subpart.",
          "citations": [
            "40 CFR 63.7082(j)"
          ]
        },
        {
          "criterion": "If the material in question is an open material storage pile, then those open material storage piles are not subject to this subpart.",
          "citations": [
            "40 CFR 63.7082(k)"
          ]
        },
        {
          "criterion": "If you wish to claim area source status, then you must measure the emissions of hydrogen chloride from all lime kilns (subject to the exceptions left to the permitting authority) using EPA Method 320 or 321 or the specified ASTM alternative as set out in §63.7142.",
          "citations": [
            "40 CFR 63.7142(a)"
          ]
        }
      ]
    },
    {
      "subpart": "A",
      "title": "General Provisions (NESHAP General Provisions)",
      "criteria": [
        {
          "criterion": "If your affected source is required to do performance testing by a relevant standard, then you must perform the required performance tests within 180 days of the compliance date for that source unless a waiver or other exception applies.",
          "citations": [
            "40 CFR 63.7(a)(2)"
          ]
        },
        {
          "criterion": "If continuous monitoring systems (CMS) are required by a relevant standard, then the monitoring requirements in §63.8 apply to those CMS (including installation, operation, QA and reporting requirements) upon promulgation of CMS performance specifications as specified in the relevant standard.",
          "citations": [
            "40 CFR 63.8(a)(1)",
            "40 CFR 63.8(a)(2)"
          ]
        },
        {
          "criterion": "If a collection of equipment, activities, or both within a single contiguous area and under common control is included in a section 112(c) source category or subcategory, then that collection is an 'affected source' as defined in §63.2 (and is subject to the relevant section 112(d) standard unless otherwise specified).",
          "citations": [
            "40 CFR 63.2 (Affected source)"
          ]
        },
        {
          "criterion": "If the plant emits or has the potential to emit any single HAP at a rate of 9.07 megagrams (10 tons) or more per year or any combination of HAP at a rate of 22.68 megagrams (25 tons) or more per year, then it meets the 'major source' definition in §63.2 and the major-source thresholds referenced in §63.7081 apply.",
          "citations": [
            "40 CFR 63.2 (Major source)",
            "40 CFR 63.7081(a)(2)"
          ]
        },
        {
          "criterion": "If a CMS is required, then you must operate and maintain each CMS consistent with good air pollution control practices and the CMS provisions in §63.8 (including QA/QC, performance evaluations, and recordkeeping/reporting requirements).",
          "citations": [
            "40 CFR 63.8(c)(1)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Confirm whether the kiln is used to produce a 'lime product' (e.g., calcium oxide/quicklime or dead burned dolomite) by calcination versus only reprocessing non-calcareous wastes; list feedstock(s) (e.g., limestone, dolomite, shells, calcium carbonate lime mud).",
    "Determine whether the kiln's calcination of calcium carbonate lime mud (from caustic recovery) results in a lime product (quicklime) as defined by the rule (i.e., is the output chemically and functionally a lime product).",
    "Quantify actual and potential annual HAP emissions (by pollutant and combined) from the entire plant to determine major-source status (>=10 tpy single HAP or >=25 tpy combined HAP).",
    "Verify whether the LMP is located at or part of any of the excluded facility types (kraft pulp mill, soda pulp mill, sulfite pulp mill, beet sugar manufacturing plant) or only processes calcium carbonate sludge from water softening.",
